// The day's affirmation in Ukrainian, for the country pages in Ukrainian. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Сьогодні не треба встигнути все. Достатньо наступної маленької справи.\", \"Втома — це не поразка. Ти втомилася, бо щодня знову поруч.\", \"Посуд може почекати. Ти маєш право посидіти п’ять хвилин.\", \"Пластівці на вечерю — це теж нагодована родина.\", \"Відпочинок не треба заслуговувати. Ти можеш відпочити просто зараз.\", \"Іноді перемога — це те, що всі дожили до часу спати. І це справжня перемога.\", \"Ти робиш більше, ніж хтось бачить. Я це бачу.\", \"Безлад у домі й улюблені діти. Це добрий обмін.\", \"У важкий день твоє найкраще виглядає інакше, і воно все одно рахується.\", \"Один глибокий вдих. Опусти плечі. У тебе все виходить.\", \"Сьогодні можна опустити планку. Іншого дня ти знову її піднімеш.\", \"Попросити про допомогу — це сила, а не слабкість.\", \"Ти маєш право сказати «ні» ще одній справі.\", \"Якщо сьогодні тобі було самотньо, ти не єдина мама, яка так почувалася. Нас багато.\", \"Ти заслуговуєш на подругу, яка запитає, як ти, і дочекається відповіді.\", \"Це нормально — написати першою. Більшість мам чекають, що хтось це зробить.\", \"Те, що тебе не помічають, не означає, що ти не важлива. Ти дуже важлива.\", \"Твої почуття мають сенс. Ти не «занадто».\", \"Тут не треба пояснювати свій важкий день. Ми розуміємо.\", \"Повідомлення іншій мамі зі словами «у мене теж» може змінити цілий день.\", \"Нагодувати, переповити, заколисати — і знову. Це справжня робота, навіть коли здається, що ти просто сидиш.\", \"Ти і твоє маля ще тільки знайомитеся. Нікуди не треба поспішати.\", \"Дні з новонародженим довгі. Цей період не триватиме вічно.\", \"Якщо сьогодні ти лише тримала маленьку людину ситою й у теплі, ти зробила величезну роботу.\", \"Не треба швидко ставати такою, як раніше. Можна просто бути там, де ти зараз.\", \"Хоч би як харчувалося твоє маля, ти про нього дбаєш. Це головне.\", \"Можна недосипати й бути сповненою любові водночас.\", \"Тримай маля на руках і відпусти хатні справи. Дім нікуди не дінеться.\", \"Істерика в магазині не робить тебе поганою мамою. Це лише означає, що в тебе малюк.\", \"Малеча перевіряє межі, бо поруч із тобою почувається в безпеці.\", \"Сьогодні ти зберігала спокій на хвилину довше, ніж учора. Це важливо.\", \"Якщо ти зірвалася, обійми і «вибач» багато що виправлять. І навчать їх чогось доброго.\", \"Липкі ручки, гучні голоси, великі почуття. Ти виховуєш цілу людину.\", \"П’яте «чому?» за годину — це маленький розум, що росте.\", \"Для щасливого спогаду не потрібен ідеальний день.\", \"Грюкнуті двері — не кінець історії. Залиш світло увімкненим.\", \"Твій підліток, може, і не скаже цього, але твоя постійна присутність важить.\", \"Бути тією, хто зберігає спокій у домі, — важка праця. І ти з нею справляєшся.\", \"Деякі з найкращих розмов стаються в машині. Просто їдь далі.\", \"Вони віддаляються, щоб вирости, а не щоб залишити тебе позаду.\", \"Не обов’язково знати всі відповіді. Уміти слухати — це вже багато.\", \"Великим дітям ти досі потрібна, просто тихіше.\", \"Тягнути все самій — це сила, якої більшість людей ніколи не бачить.\", \"Ти достатньо добра мама для своєї дитини. Ти завжди нею була.\", \"Одні руки, сто справ. Будь до себе лагіднішою.\", \"Твої діти, дивлячись на тебе, вчаться, якою буває сильна й любляча людина.\", \"Перерва — це не втеча з посту. Так ти тримаєшся далі.\", \"Ніхто не рахує балів. Важать любов і те, що ти поруч.\", \"Горе і любов мають одне джерело. Те, як сильно ти сумуєш, показує, як сильно ти любила.\", \"Для горя немає правильного розкладу. Дай собі стільки часу, скільки потрібно.\", \"У важкі річниці будь до себе такою ж ніжною, як була б до подруги.\", \"Ти можеш носити в собі смуток і все одно сміятися з дітьми. І те, і те справжнє.\", \"Якщо ти втратила вагітність або дитину, ця втрата справжня, і твоя любов теж.\", \"Буває, що горе тихе, а буває — гучне. І те, і те нормально.\", \"Мало грошей не означає мало любові.\", \"Твої діти пам’ятатимуть час із тобою більше, ніж речі, які ти купила.\", \"Питати про допомогу з рахунками — це розумно, а не соромно. Саме для цього вона й існує.\", \"Безкоштовний день у парку може стати найкращим днем тижня.\", \"Ти розтягнула гроші ще на тиждень. Для цього потрібна справжня вправність.\", \"Тривога про гроші виснажує. Ти несеш багато, і ти досі тут.\", \"Сьогодні ти випила склянку води. Почни з цього.\", \"Усі вийшли з дому. Може, взуття було не до пари. Однаково перемога.\", \"Ти зробила той дзвінок, якого боялася. Це було сміливо.\", \"Ти сьогодні сміялася. Збережи це.\", \"Тепла їжа, чиста футболка, казка на ніч. Із дрібниць складається дитинство.\", \"Сьогодні ти була доброю до когось, навіть якщо лише до себе.\", \"Поступ, а не ідеальність. Сьогодні ти зробила крок уперед.\", \"Ти закінчила одну справу зі списку. Це на одну більше, ніж жодної.\", \"Ти добра мама. Те, що ти через це переживаєш, показує, як тобі не байдуже.\", \"Ти більше, ніж те, що встигаєш зробити за день.\", \"Твоїм дітям не потрібна ідеальна мама. Їм потрібна ти, і ти в них є.\", \"Будь до себе такою ж терплячою, як до своїх дітей.\", \"Ти маєш право займати місце, чогось хотіти і мати власні мрії.\", \"Помилка не скасовує любові. Завтра — новий початок.\", \"Для когось ти цілий світ, і водночас ти — окрема людина.\", \"Це нормально — не любити кожну хвилину. Ти все одно можеш любити своїх дітей усім серцем.\", \"Немає одного правильного способу бути мамою. Твій спосіб теж має право бути.\", \"Як у позі дерева, хитатися — це нормально. Ти знову знайдеш рівновагу.\", \"Упрись ногами, як у позі гори. Ти стоїш твердіше, ніж тобі здається.\", \"Воїн два: сильні ноги, розкриті руки. Це ти, коли зустрічаєш цей тиждень.\", \"Вдих на чотири, видих на чотири. Ти тут, і в тебе все виходить.\", \"Розкрийся широко, як зірка. Ти маєш право займати місце.\", \"Широке низьке присідання важко втримати. Довгий день теж. А ти тримаєшся.\", \"Ти можеш нахилитися, як місяць-серпик, і все одно стояти.\", \"Не обов’язково вже діставати до пальців ніг. Кожна дещиця розтяжки рахується.\", \"Поза трикутника: одна рука донизу, друга догори. Стій міцно й тягнися далі.\", \"Уже пізно. Те, що не встигла сьогодні, почекає до завтра.\", \"Не спиш із малям у таку годину? Безліч мам зараз не спить разом із тобою.\", \"У домі тихо. Ця мить — твоя. Дихай.\", \"Ти прожила цей день. Більше сьогодні нічого й не треба було.\", \"Якщо цієї ночі думки не дають спокою, запиши їх і нехай почекають до ранку.\", \"Дай очам відпочити. Завтра можна почати знову.\", \"Свята бувають і важкими, і радісними. Хоч би що ти відчувала цієї пори, це нормально.\", \"Стіл не мусить бути ідеальним. Найважливіше — люди довкола нього.\", \"Якщо цього року тобі когось бракує за столом, будь ніжною до свого серця.\", \"Дякую, мамо, за кожну страву, кожну поїздку і кожні обійми.\", \"Не обов’язково приймати гостей, пекти чи весь час усміхатися. Прості свята — однаково свята.\", \"Найкращий подарунок, який отримають твої діти цього року, — час із тобою.\", \"Скромне свято теж сповнене любові. Не треба багато грошей, щоб зробити його особливим.\", \"Холодні дні, теплі обійми. Ти — тепле місце у своєму домі.\", \"Можна пропустити частину святової метушні. Спокій — теж подарунок.\", \"Якщо цього року ця пора тобі важка, ти не сама. Один день за раз.\"]";D.body.appendChild(e)})();
